urls={'rs104894050':'https://api.ncbi.nlm.nih.gov/variation/v0/beta/refsnp/104894050','clinvar_search':'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=clinvar&term=600725.0015&retmode=json','rs28936675':'https://api.ncbi.nlm.nih.gov/variation/v0/beta/refsnp/28936675'}
def fetch(kv):
 k,u=kv
 try:
  b=urllib.request.urlopen(u).read();open(k+'.json','wb').write(b);d=json.loads(b)
  if k.startswith('rs'):
   s=d.get('primary_snapshot_data',{});return k,[(p['seq_id'],[a['hgvs'] for a in p['alleles']]) for p in s.get('placements_with_allele',[]) if p['seq_id'] in ['NC_000007.14','NM_000193.4']],s.get('allele_annotations',[])
  return k,d
 except Exception as e:return k,str(e)
for r in concurrent.futures.ThreadPoolExecutor().map(fetch,urls.items()):print(r)
PY"

