import urllib.request,concurrent.futures,xml.etree.ElementTree as ET
urls={'clinvar_8891':'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=clinvar&id=8891&rettype=vcv&retmode=xml','clinvar_0002_search':'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=clinvar&term=600725.0002&retmode=json'}
def fetch(kv):
 k,u=kv
 try:
  b=urllib.request.urlopen(u).read();open(k+'.xml' if k=='clinvar_8891' else k+'.json','wb').write(b)
  if k=='clinvar_8891':
   root=ET.fromstring(b)
   return k,[(n.tag,n.attrib,n.text) for n in root.iter() if n.tag in ['VariationArchive','SequenceLocation','XRef','ProteinExpression','NucleotideExpression','Classification','Description','SimpleAllele']]
  return k,b.decode()
 except Exception as e:return k,str(e)
for r in concurrent.futures.ThreadPoolExecutor().map(fetch,urls.items()):print(r)
PY"
